-- SCHEMA CONTRACT: OTC2 staff_sync replica
-- staffs columns after this migration:
--   id uuid PK (local, never overwritten)
--   otc_staff_sync_id uuid UNIQUE (sync-only = OTC2 staff_sync.id)
--   display_name, full_name, chinese_name, position, user_role, status
--   work_email, private_email, work_phone, private_phone, profile_pic_url
--   base_location, team_name, company_list_id, brand_list_id
--   entry_date, termination_date, synced_at, created_at, updated_at
-- Forbidden on staffs: team_id, office, department, business_unit, bubble_staff_id
-- brand_list.otc_id = OTC2 nosbrand.id

-- 1) New identity + FK + chinese_name
ALTER TABLE public.staffs
  ADD COLUMN IF NOT EXISTS otc_staff_sync_id uuid,
  ADD COLUMN IF NOT EXISTS chinese_name text,
  ADD COLUMN IF NOT EXISTS company_list_id uuid,
  ADD COLUMN IF NOT EXISTS brand_list_id uuid;

-- 2) Rename team_id -> team_name
DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = 'public' AND table_name = 'staffs' AND column_name = 'team_id'
  ) AND NOT EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = 'public' AND table_name = 'staffs' AND column_name = 'team_name'
  ) THEN
    ALTER TABLE public.staffs RENAME COLUMN team_id TO team_name;
  END IF;
END $$;

-- 3) Backfill otc_staff_sync_id from OTC2 staff_sync.id via bubble_staff_id
UPDATE public.staffs AS s
SET otc_staff_sync_id = v.sync_id
