  ON public.staffs (otc_staff_sync_id)
  WHERE otc_staff_sync_id IS NOT NULL;

-- 4) brand_list.otc_id (nosbrand.id). Seeded brand_list ids already match nosbrand.
ALTER TABLE public.brand_list
  ADD COLUMN IF NOT EXISTS otc_id uuid;

UPDATE public.brand_list AS b
SET otc_id = v.otc_id
FROM (VALUES
  ('BSC'::text,     'b056bcb8-67b5-592f-b265-711df4b657f1'::uuid),
  ('BWG',           '0176f0cb-4064-502d-9138-a8b3869285c3'),
  ('BWL',           '1bbb9536-cae7-54f0-a3ce-993711c2cf46'),
  ('CFA',           '32915d65-1a44-588d-8368-d3eeb9f15803'),
  ('Wine',          '3b345631-6870-5924-9eb7-347e28a27fa8'),
  ('BWF',           '3b7d3552-6335-5f04-894b-bb00bf52d7e2'),
  ('OB',            '51a53fa6-39cb-5a22-981a-d36eb1fc27b2'),
  ('BWC',           '5f00ae87-869c-5bab-a5c9-fd6e4cecac64'),
  ('BWE',           '6cdba1ef-7edb-5452-896a-e421e078c745'),
  ('BWD',           '74c13191-55d0-5074-bc5e-65bbb3934dc9'),
  ('FC Shop',       '8fbb1a4a-7571-5a53-ad1d-15db67b7be59'),
  ('CFB',           'a02f5d1c-3584-597d-834d-7fbbb09e7ca7'),
  ('CF',            'aefe9a23-6e4b-5ba1-98f1-16243ff3260c'),
  ('BWA',           'f13c0169-6513-58be-bd6d-baa3fd813cc5'),
  ('FCC',           'f1f8a3a6-187f-58a9-8270-428df26c6666'),
  ('BWT',           'fed21b87-cf60-51cd-881f-99c4014c72a4')
) AS v(brand_code, otc_id)
WHERE b.brand_code = v.brand_code
  AND b.otc_id IS DISTINCT FROM v.otc_id;

CREATE UNIQUE INDEX IF NOT EXISTS brand_list_otc_id_key
  ON public.brand_list (otc_id)
  WHERE otc_id IS NOT NULL;

-- 5) FKs
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint WHERE conname = 'staffs_company_list_id_fkey'
  ) THEN
    ALTER TABLE public.staffs
      ADD CONSTRAINT staffs_company_list_id_fkey
      FOREIGN KEY (company_list_id) REFERENCES public.company_list(uuid) ON DELETE SET NULL;
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint WHERE conname = 'staffs_brand_list_id_fkey'
  ) THEN
    ALTER TABLE public.staffs
      ADD CONSTRAINT staffs_brand_list_id_fkey
      FOREIGN KEY (brand_list_id) REFERENCES public.brand_list(id) ON DELETE SET NULL;
  END IF;
END $$;

CREATE INDEX IF NOT EXISTS staffs_company_list_id_idx ON public.staffs (company_list_id);
CREATE INDEX IF NOT EXISTS staffs_brand_list_id_idx ON public.staffs (brand_list_id);

-- 6) Drop confirmed unused staffs columns
ALTER TABLE public.staffs
  DROP COLUMN IF EXISTS bubble_staff_id,
  DROP COLUMN IF EXISTS office,
  DROP COLUMN IF EXISTS department,
  DROP COLUMN IF EXISTS business_unit,
  DROP COLUMN IF EXISTS probation_status,
  DROP COLUMN IF EXISTS joining_date,
  DROP COLUMN IF EXISTS birthday,
  DROP COLUMN IF EXISTS al_quota,
  DROP COLUMN IF EXISTS voov_id,
  DROP COLUMN IF EXISTS team_role,
  DROP COLUMN IF EXISTS bubble_created_date,
  DROP COLUMN IF EXISTS bubble_modified_date;

DROP INDEX IF EXISTS public.idx_staffs_bubble_id;
DROP INDEX IF EXISTS public.staffs_bubble_staff_id_key;
DROP INDEX IF EXISTS public.idx_staffs_team;

CREATE INDEX IF NOT EXISTS idx_staffs_team_name ON public.staffs (team_name);

COMMENT ON COLUMN public.staffs.otc_staff_sync_id IS
  'OTC2 staff_sync.id. Sync conflict key only. App logic uses staffs.id.';
COMMENT ON COLUMN public.staffs.team_name IS
  'OTC2 staff_sync.team_name (display). Not a UUID.';
COMMENT ON COLUMN public.brand_list.otc_id IS
  'OTC2 nosbrand.id.';
